import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Reparacion } from '../../reparaciones/entities/reparacion.entity';
import { Mecanico } from '../../mecanicos/entities/mecanico.entity';

@Injectable()
export class AsignarMecanicoRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Reparacion) private readonly reparaciones: Repository<Reparacion>,
    @InjectRepository(Mecanico) private readonly mecanicos: Repository<Mecanico>
  ) {}

  buscarReparacionRepository(reparacionId: number) {
    return this.reparaciones.findOneBy({ id: reparacionId });
  }

  buscarMecanicoRepository(mecanicoId: number) {
    return this.mecanicos.findOneBy({ id: mecanicoId });
  }

  async asignarMecanicoRepository(reparacionId: number, mecanicoId: number, rol: string) {
    const asignacion = { reparacionId, mecanicoId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarMecanicoRepository } from './repository';

@Injectable()
export class AsignarMecanicoService {
  constructor(private readonly repository: AsignarMecanicoRepository) {}

  async asignarMecanicoService(reparacionId: number, mecanicoId: number, rol: string) {
    const reparacion = await this.repository.buscarReparacionRepository(reparacionId);
    const mecanico = await this.repository.buscarMecanicoRepository(mecanicoId);
    if (!reparacion || !mecanico) {
      throw new NotFoundException('No existe la reparacion o el mecanico');
    }

    try {
      return await this.repository.asignarMecanicoRepository(reparacionId, mecanicoId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El mecanico ya está asignado a esa reparacion');
      }
      throw error;
    }
  }
}

